CREATE TABLE docs (
    id bigserial PRIMARY KEY,
    body text,
    embedding vector(384)          -- one 384-number embedding per row
);

-- the 5 most similar documents to a query vector
SELECT id, body
FROM docs
ORDER BY embedding <=> '[0.12, 0.03, ...]'
LIMIT 5;

